import leetcode.medium.OnlineStockSpan;

import org.junit.Assert;
import org.junit.Test;

public class OnlineStockSpanTest {

    @Test
    public void nextTestWithSinglePrice() {
        OnlineStockSpan span = new OnlineStockSpan();
        int result = span.next(100);
        Assert.assertEquals(1, result);
    }

    @Test
    public void nextTestWithLowerPrice() {
        OnlineStockSpan span = new OnlineStockSpan();
        span.next(100);
        int result = span.next(80);
        Assert.assertEquals(1, result);
    }

    @Test
    public void nextTestWithHigherPrice() {
        OnlineStockSpan span = new OnlineStockSpan();
        span.next(100);
        int result = span.next(120);
        Assert.assertEquals(2, result);
    }

    @Test
    public void nextTestWithMixedPrices() {
        OnlineStockSpan span = new OnlineStockSpan();
        span.next(100);
        span.next(80);
        span.next(60);
        int result = span.next(120);
        Assert.assertEquals(4, result);
    }

    @Test
    public void calculateSpansTestWithSinglePrice() {
        OnlineStockSpan span = new OnlineStockSpan();
        int[] result = span.calculateSpans(new int[] {100});
        Assert.assertArrayEquals(new int[] {1}, result);
    }

    @Test
    public void calculateSpansTestWithAscendingPrices() {
        OnlineStockSpan span = new OnlineStockSpan();
        int[] result = span.calculateSpans(new int[] {100, 105, 110, 120});
        Assert.assertArrayEquals(new int[] {1, 2, 3, 4}, result);
    }

    @Test
    public void calculateSpansTestWithDescendingPrices() {
        OnlineStockSpan span = new OnlineStockSpan();
        int[] result = span.calculateSpans(new int[] {120, 110, 100, 90});
        Assert.assertArrayEquals(new int[] {1, 1, 1, 1}, result);
    }

    @Test
    public void calculateSpansTestWithMixedPrices() {
        OnlineStockSpan span = new OnlineStockSpan();
        int[] result = span.calculateSpans(new int[] {100, 110, 90, 120, 105});
        Assert.assertArrayEquals(new int[] {1, 2, 1, 4, 1}, result);
    }
}
